<script setup lang="ts">
import { computed, reactive, ref, onMounted } from 'vue'
import type { CatalogoEquivalencia, FcEquivalencia, FcEquivalenciaPayload, FcEquivalenciaResponse } from '../interfaces/fc-equivalencia.interface'
import { buscarCuentasEquivalencia, cambiarEstadoEquivalenciaFlujoCaja, guardarEquivalenciaFlujoCaja, listarEquivalenciasFlujoCaja, obtenerEquivalenciaFlujoCaja } from '../services/fc-equivalencia'
const emptyData = (): FcEquivalenciaResponse => ({ equivalencias: [], quiebres: [], conceptos: [], inversiones: [] })
const blank = (): FcEquivalenciaPayload => ({ cuenta_contable_id: 0, cuenta_equivalente_id: null, quiebre_id: 0, concepto_id: null, inversion_id: null, cod_presupuestal: '' })
const data = ref(emptyData()), search = ref(''), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null), originQuery = ref(''), equivalentQuery = ref(''), originOptions = ref<CatalogoEquivalencia[]>([]), equivalentOptions = ref<CatalogoEquivalencia[]>([])
const form = reactive(blank())
const filtered = computed(() => { const q = search.value.toLocaleUpperCase(); return data.value.equivalencias.filter(x => !q || `${x.cuenta_contable?.cta_contable} ${x.cuenta_contable?.descripcion} ${x.quiebre?.nombre} ${x.concepto?.nombre} ${x.cod_presupuestal || ''}`.toLocaleUpperCase().includes(q)) })
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
const accountText = (x?: CatalogoEquivalencia | null) => x ? `${x.cta_contable || x.codigo || ''} · ${x.descripcion || x.nomb_cta || x.nombre || ''}` : ''
const breakText = (x?: FcEquivalencia['quiebre']) => x ? [x.padre?.padre?.nombre, x.padre?.nombre, x.nombre].filter(Boolean).join(' / ') : '-'
async function load() { loading.value = true; error.value = ''; try { data.value = await listarEquivalenciasFlujoCaja() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, blank()); originQuery.value = ''; equivalentQuery.value = ''; showForm.value = true }
async function findAccounts(target: 'origin' | 'equivalent') { const q = target === 'origin' ? originQuery.value : equivalentQuery.value; if (q.trim().length < 2) return; try { const values = await buscarCuentasEquivalencia(q.trim()); if (target === 'origin') originOptions.value = values; else equivalentOptions.value = values } catch (e) { error.value = message(e) } }
function selectAccount(item: CatalogoEquivalencia, target: 'origin' | 'equivalent') { if (target === 'origin') { form.cuenta_contable_id = item.id; originQuery.value = accountText(item); originOptions.value = [] } else { form.cuenta_equivalente_id = item.id; equivalentQuery.value = accountText(item); equivalentOptions.value = [] } }
async function edit(item: FcEquivalencia) { loading.value = true; try { const x = await obtenerEquivalenciaFlujoCaja(item.id); editing.value = x.id; Object.assign(form, { cuenta_contable_id: x.cuenta_contable_id, cuenta_equivalente_id: x.cuenta_equivalente_id || null, quiebre_id: x.quiebre_id, concepto_id: x.concepto_id || null, inversion_id: x.inversion_id || null, cod_presupuestal: x.cod_presupuestal || '' }); originQuery.value = accountText(x.cuenta_contable); equivalentQuery.value = accountText(x.cuenta_equivalente); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { if (form.cuenta_equivalente_id && form.cuenta_contable_id === form.cuenta_equivalente_id) { error.value = 'La cuenta equivalente no puede ser igual a la cuenta contable origen.'; return } loading.value = true; error.value = ''; try { await guardarEquivalenciaFlujoCaja(editing.value, { ...form }); success.value = `Equivalencia ${editing.value ? 'actualizada' : 'registrada'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: FcEquivalencia) { const action = item.activo ? 'inactivar' : 'activar'; if (!confirm(`¿Desea ${action} esta equivalencia?`)) return; loading.value = true; try { await cambiarEstadoEquivalenciaFlujoCaja(item.id); success.value = `Equivalencia ${item.activo ? 'inactivada' : 'activada'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Equivalencias de flujo de caja</nav><header class="hero"><div class="mark">EQ</div><div><small>MIA · FINANZAS · FLUJO DE CAJA</small><h1>Equivalencias de flujo de caja</h1><p>Relaciona cuentas de tesorería con quiebres, conceptos e inversiones.</p></div><strong>{{filtered.length}} equivalencias</strong><button @click="create">+ Nueva equivalencia</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="filters"><input v-model.trim="search" placeholder="Buscar cuenta, quiebre, concepto o código presupuestal"><button class="soft" @click="search=''">Limpiar</button></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!filtered.length" class="empty">No hay equivalencias registradas.</div><div v-else class="scroll"><table><thead><tr><th>Cuenta origen</th><th>Cuenta equivalente</th><th>Quiebre</th><th>Concepto</th><th>Inversión</th><th>Cód. presupuestal</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><b>{{item.cuenta_contable?.cta_contable}}</b><small>{{item.cuenta_contable?.descripcion}}</small></td><td><b>{{item.cuenta_equivalente?.cta_contable||'-'}}</b><small>{{item.cuenta_equivalente?.descripcion}}</small></td><td>{{breakText(item.quiebre)}}</td><td>{{item.concepto?.nombre||'-'}}</td><td>{{item.inversion?.nombre||'-'}}</td><td>{{item.cod_presupuestal||'-'}}</td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} equivalencia</h2></div><button type="button" @click="showForm=false">×</button></header><div class="twocol"><label>Cuenta contable origen<div class="lookup"><input v-model.trim="originQuery" required placeholder="Buscar cuenta de tesorería" @input="form.cuenta_contable_id=0;findAccounts('origin')"><ul v-if="originOptions.length"><li v-for="x in originOptions" :key="x.id" @click="selectAccount(x,'origin')">{{accountText(x)}}</li></ul></div></label><label>Cuenta equivalente (opcional)<div class="lookup"><input v-model.trim="equivalentQuery" placeholder="Buscar cuenta equivalente" @input="form.cuenta_equivalente_id=null;findAccounts('equivalent')"><ul v-if="equivalentOptions.length"><li v-for="x in equivalentOptions" :key="x.id" @click="selectAccount(x,'equivalent')">{{accountText(x)}}</li></ul></div></label></div><label>Quiebre<select v-model.number="form.quiebre_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in data.quiebres" :key="x.id" :value="x.id">{{x.texto||x.nombre}}</option></select></label><div class="twocol"><label>Concepto<select v-model="form.concepto_id"><option :value="null">Sin concepto</option><option v-for="x in data.conceptos" :key="x.id" :value="x.id">{{x.codigo||x.id}} · {{x.nombre}}</option></select></label><label>Inversión<select v-model="form.inversion_id"><option :value="null">Sin inversión</option><option v-for="x in data.inversiones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><label>Código presupuestal<input v-model.trim="form.cod_presupuestal" maxlength="30"></label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading||!form.cuenta_contable_id">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1fr auto;gap:7px;background:#fff}.filters input,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#809096}.good,.bad{padding:4px 8px;border-radius:10px;font-size:.42rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(780px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px}.lookup{position:relative}.lookup ul{position:absolute;z-index:5;width:100%;margin:2px 0;padding:0;border:1px solid #d5dfe2;background:#fff;list-style:none;box-shadow:0 8px 18px #19374622}.lookup li{padding:8px;font-size:.47rem;cursor:pointer}.lookup li:hover{background:#edf6f7}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
